.markdown-preview-view hr.background-image:
linear-gradient(
    90deg,
    var(--lcars-orange) 0,
    var(--lcars-orange) 64px,
    transparent 64px,
    transparent 72px,
    var(--lcars-peri) 72px,
    var(--lcars-peri) calc(100% - 30px),
    transparent calc(100% - 30px),
    transparent calc(100% - 22px),
    var(--lcars-orange) calc(100% - 22px)
  )

.nav-header::before.background-image:
linear-gradient(
    90deg,
    var(--lcars-orange) 0,
    var(--lcars-orange) 22px,
    transparent 22px,
    transparent 28px,
    var(--lcars-peri) 28px,
    var(--lcars-peri) calc(100% - 14px),
    transparent calc(100% - 14px),
    transparent calc(100% - 8px),
    var(--lcars-orange) calc(100% - 8px)
  )
